using System.IO.Compression;
using System.Text;
using System.Text.Json;

namespace Panacea.Sim.Tests;

/// <summary>Access to the parity fixtures generated by packages/playtest/src/cli/parity-fixtures.ts.</summary>
public static class Fixtures
{
    public static readonly ContentPack Content = Sim.Content.LoadEmbedded();

    public static string Dir
    {
        get
        {
            string copied = Path.Combine(AppContext.BaseDirectory, "fixtures");
            if (File.Exists(Path.Combine(copied, "manifest.json"))) return copied;
            // Fall back to the source tree (e.g. when run from an IDE without the copy step).
            var dir = new DirectoryInfo(AppContext.BaseDirectory);
            while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "fixtures", "manifest.json"))) dir = dir.Parent;
            return dir is null ? copied : Path.Combine(dir.FullName, "fixtures");
        }
    }

    public static string ReadText(string relativePath)
    {
        string path = Path.Combine(Dir, relativePath);
        if (!path.EndsWith(".gz", StringComparison.Ordinal)) return File.ReadAllText(path, Encoding.UTF8);
        using var file = File.OpenRead(path);
        using var gz = new GZipStream(file, CompressionMode.Decompress);
        using var reader = new StreamReader(gz, Encoding.UTF8);
        return reader.ReadToEnd();
    }

    public static JsonDocument ReadJson(string relativePath) => JsonDocument.Parse(ReadText(relativePath));

    public static IEnumerable<object[]> RunFiles()
    {
        using var manifest = ReadJson("manifest.json");
        foreach (var run in manifest.RootElement.GetProperty("runs").EnumerateArray())
            yield return [run.GetProperty("file").GetString()!];
    }

    public static double FromBits(string hex) => BitConverter.Int64BitsToDouble(unchecked((long)Convert.ToUInt64(hex, 16)));

    public static string Bits(double x) => unchecked((ulong)BitConverter.DoubleToInt64Bits(x)).ToString("x16");

    /// <summary>The first JSON paths at which two documents differ (up to <paramref name="max"/>).</summary>
    public static List<string> Diff(JsonElement expected, JsonElement actual, int max = 12)
    {
        var diffs = new List<string>();
        Walk(expected, actual, "$", diffs, max);
        return diffs;
    }

    private static void Walk(JsonElement e, JsonElement a, string path, List<string> diffs, int max)
    {
        if (diffs.Count >= max) return;
        if (e.ValueKind != a.ValueKind)
        {
            diffs.Add($"{path}: expected {Short(e)}, got {Short(a)}");
            return;
        }
        switch (e.ValueKind)
        {
            case JsonValueKind.Object:
            {
                var ep = e.EnumerateObject().ToDictionary(p => p.Name, p => p.Value, StringComparer.Ordinal);
                var ap = a.EnumerateObject().ToDictionary(p => p.Name, p => p.Value, StringComparer.Ordinal);
                foreach (var key in ep.Keys.Union(ap.Keys).OrderBy(k => k, StringComparer.Ordinal))
                {
                    if (diffs.Count >= max) return;
                    string p = $"{path}.{key}";
                    if (!ap.TryGetValue(key, out var av)) diffs.Add($"{p}: missing (expected {Short(ep[key])})");
                    else if (!ep.TryGetValue(key, out var ev)) diffs.Add($"{p}: unexpected {Short(av)}");
                    else Walk(ev, av, p, diffs, max);
                }
                break;
            }
            case JsonValueKind.Array:
            {
                int el = e.GetArrayLength(), al = a.GetArrayLength();
                for (int i = 0; i < Math.Min(el, al); i++) Walk(e[i], a[i], $"{path}[{i}]", diffs, max);
                if (el != al && diffs.Count < max) diffs.Add($"{path}: expected length {el}, got {al}");
                break;
            }
            case JsonValueKind.Number:
                if (e.GetDouble() != a.GetDouble() || e.GetRawText() != a.GetRawText())
                    diffs.Add($"{path}: expected {e.GetRawText()}, got {a.GetRawText()}");
                break;
            default:
                if (e.GetRawText() != a.GetRawText()) diffs.Add($"{path}: expected {Short(e)}, got {Short(a)}");
                break;
        }
    }

    private static string Short(JsonElement x)
    {
        string s = x.GetRawText();
        return s.Length > 120 ? s[..120] + "…" : s;
    }
}
